import sys

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    values = data[1:]

    # exponents[p][i] = exponent of p in A_i
    exponents = {}
    for i, value in enumerate(values):
        x = value
        d = 2
        while d * d <= x:
            if x % d == 0:
                cnt = 0
                while x % d == 0:
                    x //= d
                    cnt += 1
                exponents.setdefault(d, [0] * (n - 1))[i] = cnt
            d += 1
        if x > 1:
            exponents.setdefault(x, [0] * (n - 1))[i] = 1

    answer = 1
    for p, edge_exp in exponents.items():
        # A prime's valuation sequence is a walk. Its increment across edge i
        # is either +a_i or -a_i, as coprimality assigns p wholly to one side.
        # Shift the walk so its minimum is zero; this is exactly the gcd=1 rule.
        bound = sum(edge_exp)
        p_power = [1] * (bound + 1)
        for h in range(1, bound + 1):
            p_power[h] = p_power[h - 1] * p % MOD

        # dp_not_zero[h], dp_zero[h]: total weights ending at height h,
        # respectively without/with having visited height zero.
        # The first vertex may start at any height in [0,bound].
        dp_not_zero = [0] * (bound + 1)
        dp_zero = [0] * (bound + 1)
        for h in range(bound + 1):
            if h == 0:
                dp_zero[h] = 1
            else:
                dp_not_zero[h] = p_power[h]

        for a in edge_exp:
            nxt_not_zero = [0] * (bound + 1)
            nxt_zero = [0] * (bound + 1)
            for h in range(bound + 1):
                v0 = dp_not_zero[h]
                v1 = dp_zero[h]
                if not (v0 or v1):
                    continue
                # When a=0 the two assignments coincide and count only once.
                destinations = (h,) if a == 0 else (h - a, h + a)
                for nh in destinations:
                    if 0 <= nh <= bound:
                        weight = p_power[nh]
                        if nh == 0:
                            nxt_zero[0] = (nxt_zero[0] + (v0 + v1) * weight) % MOD
                        else:
                            if v0:
                                nxt_not_zero[nh] = (nxt_not_zero[nh] + v0 * weight) % MOD
                            if v1:
                                nxt_zero[nh] = (nxt_zero[nh] + v1 * weight) % MOD
            dp_not_zero, dp_zero = nxt_not_zero, nxt_zero

        answer = answer * (sum(dp_zero) % MOD) % MOD

    print(answer)

