import sys

def main():
    data=list(map(int,sys.stdin.buffer.read().split()))
    if not data: return
    it=iter(data); n=next(it); q=next(it)
    parent=list(range(n+1)); size=[1]*(n+1); left=list(range(n+1)); right=list(range(n+1)); color=list(range(n+1))
    count=[0]*(n+1)
    for i in range(1,n+1): count[i]=1
    def find(x):
        while parent[x]!=x:
            parent[x]=parent[parent[x]]
            x=parent[x]
        return x
    def merge(a,b):
        a=find(a); b=find(b)
        if a==b: return a
        # these are neighboring intervals; union by size
        if size[a]<size[b]: a,b=b,a
        parent[b]=a
        size[a]+=size[b]
        left[a]=min(left[a],left[b]); right[a]=max(right[a],right[b])
        return a
    out=[]
    for _ in range(q):
        typ=next(it)
        if typ==1:
            x=next(it); c=next(it)
            r=find(x); old=color[r]
            if old!=c:
                count[old]-=size[r]; count[c]+=size[r]
                color[r]=c
                l=left[r]; rr=right[r]
                if l>1:
                    z=find(l-1)
                    if color[z]==c: r=merge(r,z)
                rr=right[r]
                if rr<n:
                    z=find(rr+1)
                    if color[z]==c: r=merge(r,z)
        else:
            c=next(it); out.append(str(count[c]))
    sys.stdout.write('\n'.join(out))

