from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        # For each pair, order endpoints so x < y. When considering subarrays
        # ending at r >= y, their starting point must be greater than x.
        by_right = [[] for _ in range(n + 1)]
        for idx, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            by_right[b].append((a, idx))

        gains = [0] * len(conflictingPairs)
        largest = second = 0
        largest_id = -1
        base = 0

        for r in range(1, n + 1):
            for x, idx in by_right[r]:
                if x > largest:
                    second, largest, largest_id = largest, x, idx
                elif x > second:
                    second = x

            # With all pairs present, valid starts are largest+1 through r.
            base += r - largest

            # Removing the unique largest constraint lowers the threshold to
            # the second-largest endpoint. Ties naturally have zero gain.
            if largest_id >= 0:
                gains[largest_id] += largest - second

        return base + max(gains)

