import sys

def main():
    input = sys.stdin.buffer.readline
    N, M, Q = map(int, input().split())
    edges = [None] * M
    for i in range(M):
        a, b, c = map(int, input().split())
        edges[i] = (a - 1, b - 1, c)

    queries = []
    closed = set()
    for _ in range(Q):
        data = list(map(int, input().split()))
        if data[0] == 1:
            e = data[1] - 1
            closed.add(e)
            queries.append((1, e))
        else:
            queries.append((2, data[1] - 1, data[2] - 1))

    INF = 10**30
    dist = [[INF] * N for _ in range(N)]
    for i in range(N):
        dist[i][i] = 0
    for i, (a, b, c) in enumerate(edges):
        if i not in closed:
            dist[a][b] = dist[b][a] = c

    # All-pairs shortest paths in the graph after every queried closure.
    for k in range(N):
        row_k = dist[k]
        for i in range(N):
            row_i = dist[i]
            dik = row_i[k]
            if dik == INF:
                continue
            for j in range(N):
                candidate = dik + row_k[j]
                if candidate < row_i[j]:
                    row_i[j] = candidate

    answers = []
    for query in reversed(queries):
        if query[0] == 2:
            x, y = query[1], query[2]
            answers.append(-1 if dist[x][y] == INF else dist[x][y])
        else:
            a, b, weight = edges[query[1]]
            # Insert this road. Any new shortest path uses it at most once.
            col_a = [dist[i][a] for i in range(N)]
            col_b = [dist[i][b] for i in range(N)]
            row_a = dist[a][:]
            row_b = dist[b][:]
            for i in range(N):
                row_i = dist[i]
                via_a = col_a[i] + weight
                via_b = col_b[i] + weight
                for j in range(N):
                    candidate = via_a + row_b[j]
                    if candidate < row_i[j]:
                        row_i[j] = candidate
                    candidate = via_b + row_a[j]
                    if candidate < row_i[j]:
                        row_i[j] = candidate

    print("\n".join(map(str, reversed(answers))))

if __name__ == "__main__":
    main()

