import sys
import math


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, budget = data[0], data[1]
    processes = [tuple(data[2 + 4 * i: 6 + 4 * i]) for i in range(n)]

    def min_cost(target, a, p, b, q):
        if target == 0:
            return 0

        g = math.gcd(a, b)
        step = b // g
        xmax = (target + a - 1) // a
        best = 10**30

        # For a fixed x modulo step, increasing x by step changes the
        # required y by exactly a/g, so cost is linear until y reaches zero.
        # Its minimum is therefore at an endpoint or next to that boundary.
        for residue in range(min(step, xmax + 1)):
            tmax = (xmax - residue) // step
            candidates = {0, tmax}
            if tmax > 0:
                candidates.add(tmax - 1)
            for t in candidates:
                x = residue + t * step
                y = max(0, (target - a * x + b - 1) // b)
                cost = x * p + y * q
                if cost < best:
                    best = cost
        return best

    low, high = 0, budget * 100
    while low < high:
        target = (low + high + 1) // 2
        total = 0
        for a, p, b, q in processes:
            total += min_cost(target, a, p, b, q)
            if total > budget:
                break
        if total <= budget:
            low = target
        else:
            high = target - 1

    print(low)


if __name__ == '__main__':
    main()

