class Solution:
    def numberOfWays(self, n: int, x: int, y: int) -> int:
        mod = 10**9 + 7
        # dp[k] counts assignments to the processed performers, weighted by
        # y**k for the k stages currently occupied.
        dp = [1] + [0] * x

        for i in range(1, n + 1):
            ndp = [0] * (x + 1)
            for k in range(1, min(i, x) + 1):
                # Join one of k occupied stages, or open a new stage.
                ndp[k] = (k * dp[k] + (x - k + 1) * y * dp[k - 1]) % mod
            dp = ndp

        return sum(dp) % mod

