MOD = 10**9 + 7

class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        n = len(s)

        # steps[x] is the number of popcount operations needed for x to reach 1.
        steps = [0] * (n + 1)
        for x in range(2, n + 1):
            steps[x] = 1 + steps[x.bit_count()]

        # For x > 0, its first operation produces its number of set bits.
        # Thus x is k-reducible exactly when steps[popcount(x)] <= k - 1.
        good = [steps[c] <= k - 1 for c in range(n + 1)]

        # Binomial coefficients modulo MOD.
        choose = [[0] * (n + 1) for _ in range(n + 1)]
        choose[0][0] = 1
        for a in range(1, n + 1):
            choose[a][0] = 1
            for b in range(1, a + 1):
                choose[a][b] = (choose[a - 1][b - 1] + choose[a - 1][b]) % MOD

        answer = 0
        prefix_ones = 0

        # Count numbers smaller than s by choosing the first position where
        # their bit is 0 while s has 1, then choosing the remaining set bits.
        for i, bit in enumerate(s):
            if bit == '1':
                remaining = n - i - 1
                for count in range(1, n + 1):
                    if good[count]:
                        needed = count - prefix_ones
                        if 0 <= needed <= remaining:
                            answer += choose[remaining][needed]
                            answer %= MOD
                prefix_ones += 1

        return answer

