import sys
import heapq


def solve():
    input = sys.stdin.readline
    n = int(input())
    graph = [input().strip() for _ in range(n)]

    # incoming[c][v] lists x such that x -> v has label c;
    # outgoing[c][v] lists y such that v -> y has label c.
    incoming = [[[] for _ in range(n)] for _ in range(26)]
    outgoing = [[[] for _ in range(n)] for _ in range(26)]
    for u in range(n):
        for v, ch in enumerate(graph[u]):
            if ch != '-':
                c = ord(ch) - ord('a')
                outgoing[c][u].append(v)
                incoming[c][v].append(u)

    inf = 10**9
    dist = [[inf] * n for _ in range(n)]
    pq = []

    # Empty paths and one-edge paths are the centers of palindromes.
    for i in range(n):
        dist[i][i] = 0
        heapq.heappush(pq, (0, i, i))
    for i in range(n):
        for j, ch in enumerate(graph[i]):
            if ch != '-' and dist[i][j] > 1:
                dist[i][j] = 1
                heapq.heappush(pq, (1, i, j))

    while pq:
        length, u, v = heapq.heappop(pq)
        if length != dist[u][v]:
            continue
        new_length = length + 2
        for c in range(26):
            left = incoming[c][u]
            right = outgoing[c][v]
            if not left or not right:
                continue
            for x in left:
                row = dist[x]
                for y in right:
                    if new_length < row[y]:
                        row[y] = new_length
                        heapq.heappush(pq, (new_length, x, y))

    print('\n'.join(' '.join(str(-1 if value == inf else value) for value in row)
                    for row in dist))


if __name__ == '__main__':
    solve()

