import sys, random

def is_mountain(x):
    # The lowest set bit is followed by a zero exactly at mountain creases.
    if x == 0:
        return False
    t = (x & -x).bit_length() - 1
    return ((x >> (t + 1)) & 1) == 0

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    a = data[1:]
    limit = (1 << 100) - a[-1] - 1
    if limit < 1:
        print(0)
        return
    def score(x):
        return sum(is_mountain(x + y) for y in a)
    best = 0
    # Try a broad collection of shifts, then improve them by bit flips.
    rng = random.Random(917263)
    starts = [1, limit, limit // 2]
    for _ in range(20000):
        starts.append(rng.randint(1, limit))
    for x in starts:
        s = score(x)
        if s > best:
            best = s
        # Greedy coordinate ascent; restart at varied points to explore.
        for _ in range(3):
            changed = False
            for b in range(100):
                y = x ^ (1 << b)
                if 1 <= y <= limit:
                    z = score(y)
                    if z > s:
                        x, s, changed = y, z, True
                        if s > best:
                            best = s
            if not changed:
                break
    print(best)

if __name__ == '__main__':
    main()

