    n, m = data[0], data[1]
    rows = [0] * n
    pos = 2
    for _ in range(m):
        u = data[pos] - 1
        v = data[pos + 1] - 1
        pos += 2
        rows[u] |= 1 << v
        rows[v] |= 1 << u

    # Reduced row echelon form over GF(2).
    pivots = []
    rank = 0
    for col in range(n):
        pivot_row = next((i for i in range(rank, n) if (rows[i] >> col) & 1), None)
        if pivot_row is None:
            continue
        rows[rank], rows[pivot_row] = rows[pivot_row], rows[rank]
        for i in range(n):
            if i != rank and ((rows[i] >> col) & 1):
                rows[i] ^= rows[rank]
        pivots.append(col)
        rank += 1

    pivot_set = set(pivots)
    basis = []
    for free_col in range(n):
        if free_col in pivot_set:
            continue
        vec = 1 << free_col
        for i, pivot_col in enumerate(pivots):
            if (rows[i] >> free_col) & 1:
                vec |= 1 << pivot_col
        basis.append(vec)

    # A vertex must be nonzero in at least one vector of the nullspace.
