def main():
    input=sys.stdin.readline
    n,q=map(int,input().split())
    s=input().strip()
    pos={c:[] for c in '12/'}
    for i,c in enumerate(s,1): pos[c].append(i)
    ones,twos,slashes=pos['1'],pos['2'],pos['/']
    out=[]
    for _ in range(q):
        L,R=map(int,input().split())
        ilo=bisect_left(ones,L); ihi=bisect_right(ones,R)
        tlo=bisect_left(twos,L); thi=bisect_right(twos,R)
        slo=bisect_left(slashes,L); shi=bisect_right(slashes,R)
        def good(k):
            aidx=ilo+k-1
            bidx=thi-k
            if aidx>=ihi or bidx<tlo: return False
            a=ones[aidx]; b=twos[bidx]
            if a>b: return False
            j=bisect_left(slashes,a,slo,shi)
            return j<shi and slashes[j]<=b
        lo,hi=0,(R-L+1)//2
        while lo<hi:
            mid=(lo+hi+1)//2
            if good(mid): lo=mid
            else: hi=mid-1
        if lo: out.append(str(2*lo+1))
        elif slo<shi: out.append('1')
        else: out.append('0')
    print('\n'.join(out))
