from typing import List
from array import array

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        size = n * m
        # Clockwise order of diagonal directions (with rows increasing downward).
        dirs = [(1, 1), (1, -1), (-1, -1), (-1, 1)]

        # straight[d][p][i] is the maximum alternating 2/0 sequence
        # starting at cell i in direction d; p=0 expects 2, p=1 expects 0.
        straight = [[array('H', [0]) * size for _ in range(2)] for _ in range(4)]
        for d, (dr, dc) in enumerate(dirs):
            rows = range(n - 1, -1, -1) if dr > 0 else range(n)
            for r in rows:
                for c in range(m):
                    i = r * m + c
                    nr, nc = r + dr, c + dc
                    for p, value in ((0, 2), (1, 0)):
                        if grid[r][c] == value:
                            straight[d][p][i] = 1 + (
                                straight[d][1 - p][nr * m + nc]
                                if 0 <= nr < n and 0 <= nc < m else 0
                            )

        # best[d][p][i] includes i and allows a clockwise turn at most once.
        best = []
        for d, (dr, dc) in enumerate(dirs):
            turn_d = (d + 1) % 4
            tr, tc = dirs[turn_d]
            cur = [array('H', [0]) * size for _ in range(2)]
            rows = range(n - 1, -1, -1) if dr > 0 else range(n)
            for r in rows:
                for c in range(m):
                    i = r * m + c
                    nr, nc = r + dr, c + dc
                    xr, xc = r + tr, c + tc
                    for p, value in ((0, 2), (1, 0)):
                        if grid[r][c] != value:
                            continue
                        length = 0
                        if 0 <= nr < n and 0 <= nc < m:
                            length = cur[1 - p][nr * m + nc]
                        if 0 <= xr < n and 0 <= xc < m:
                            length = max(length, straight[turn_d][1 - p][xr * m + xc])
                        cur[p][i] = length + 1
            best.append(cur)

        answer = 0
        for r in range(n):
            for c in range(m):
                if grid[r][c] != 1:
                    continue
                answer = max(answer, 1)
                for d, (dr, dc) in enumerate(dirs):
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < n and 0 <= nc < m:
                        answer = max(answer, 1 + best[d][0][nr * m + nc])
        return answer

