from array import array
class Solution:
 def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
  n=len(grid); m=len(grid[0]); N=n*m
  dirs=[(1,1),(1,-1),(-1,-1),(-1,1)]
  # parity 0 expects 2, parity 1 expects 0
  H=[[array('H',[0])*N for _ in range(2)] for d in range(4)]
  for d,(dr,dc) in enumerate(dirs):
   for p in range(2):
    a=H[d][p]; want=2 if p==0 else 0
    rows=range(n-1,-1,-1) if dr>0 else range(n)
    for r in rows:
     for c in range(m):
      idx=r*m+c
      if grid[r][c]!=want: continue
      nr=r+dr; nc=c+dc
      a[idx]=1+(H[d][1-p][nr*m+nc] if 0<=nr<n and 0<=nc<m else 0)
  G=[]
