class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        h = (n + 1) // 2
        coeff = []

        # Each independent digit contributes its place value and, except
        # at the center, the place value of its mirrored digit.
        for i in range(h):
            j = n - 1 - i
            c = pow(10, n - 1 - i, k)
            if i != j:
                c = (c + pow(10, n - 1 - j, k)) % k
            coeff.append(c)

        # suffix[i] is the set of residues attainable by positions i..h-1.
        suffix = [0] * (h + 1)
        suffix[h] = 1  # only residue 0 is attainable from no positions
        for i in range(h - 1, -1, -1):
            mask = 0
            next_mask = suffix[i + 1]
            for residue in range(k):
                if (next_mask >> residue) & 1:
                    for digit in range(10):
                        new_residue = (residue + digit * coeff[i]) % k
                        mask |= 1 << new_residue
            suffix[i] = mask

        # Greedily choose the largest digit that leaves a feasible suffix.
        digits = []
        residue = 0
        for i, c in enumerate(coeff):
            min_digit = 1 if i == 0 else 0
            for digit in range(9, min_digit - 1, -1):
                needed = (-residue - digit * c) % k
                if (suffix[i + 1] >> needed) & 1:
                    digits.append(str(digit))
                    residue = (residue + digit * c) % k
                    break

        half = ''.join(digits)
        if n % 2:
            return half + half[:-1][::-1]
        return half + half[::-1]

