class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n=len(nums)
        nxt=[n]*n
        st=[]
        for i,x in enumerate(nums):
            while st and nums[st[-1]] <= x:
                nxt[st.pop()]=i
            st.append(i)
        levels=n.bit_length()
        jump=[nxt]
        for _ in range(1,levels):
            prev=jump[-1]
            jump.append([prev[prev[i]] if prev[i]<n else n for i in range(n)])
        pref=[0]
        for x in nums: pref.append(pref[-1]+x)
        def maxsum(l,r):
            cur=l; total=0
            for p in range(levels-1,-1,-1):
                end=jump[p][cur]
                if end<=r:
                    total += nums[cur]*(end-cur)
                    cur=end
            return total+nums[cur]*(r-cur+1)
        ans=0
        for r in range(n):
            lo,hi=0,r
            while lo<hi:
                mid=(lo+hi)//2
                if maxsum(mid,r)-(pref[r+1]-pref[mid])<=k: hi=mid
                else: lo=mid+1
            ans+=r-lo+1
        return ans

