class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        a, b, c = p.split('*')
        n = len(s)

        def occurrences(t):
            if not t:
                return list(range(n + 1))

            m = len(t)
            pi = [0] * m
            j = 0
            for i in range(1, m):
                while j and t[i] != t[j]:
                    j = pi[j - 1]
                if t[i] == t[j]:
                    j += 1
                pi[i] = j

            result = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != t[j]:
                    j = pi[j - 1]
                if ch == t[j]:
                    j += 1
                if j == m:
                    result.append(i - m + 1)
                    j = pi[j - 1]
            return result

        starts_a, starts_b, starts_c = map(occurrences, (a, b, c))
        best = n + 1

        for start_b in starts_b:
            # Latest A occurrence ending no later than B's start.
            i = bisect_right(starts_a, start_b - len(a)) - 1
            # Earliest C occurrence starting no earlier than B's end.
            k = bisect_left(starts_c, start_b + len(b))
            if i >= 0 and k < len(starts_c):
                best = min(best, starts_c[k] + len(c) - starts_a[i])

        return -1 if best == n + 1 else best

