class Solution:
    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        # Prefix indices with the same remainder modulo k delimit lengths
        # divisible by k. Keep the smallest such prefix seen so far.
        min_prefix = [None] * k
        min_prefix[0] = 0
        prefix = 0
        best = None

        for i, value in enumerate(nums, 1):
            prefix += value
            remainder = i % k

            if min_prefix[remainder] is not None:
                candidate = prefix - min_prefix[remainder]
                if best is None or candidate > best:
                    best = candidate

            if min_prefix[remainder] is None or prefix < min_prefix[remainder]:
                min_prefix[remainder] = prefix

