        n = len(nums)
        q = len(queries)

        def possible(k: int) -> bool:
            for i, target in enumerate(nums):
                if target == 0:
                    continue
                dp = 1  # bit s is set when sum s is achievable
                mask = (1 << (target + 1)) - 1
                for left, right, val in queries[:k]:
                    if left <= i <= right:
                        dp = (dp | (dp << val)) & mask
                        if (dp >> target) & 1:
                            break
                if not ((dp >> target) & 1):
                    return False
            return True

        if possible(0):
            return 0
        if not possible(q):
            return -1

        lo, hi = 0, q
        while lo + 1 < hi:
            mid = (lo + hi) // 2
            if possible(mid):
                hi = mid
            else:
                lo = mid
