import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        length = len(str(n))
        lo = 0 if length == 1 else 10 ** (length - 1)
        hi = 10 ** length

        # Sieve all values that can be represented with this digit length.
        prime = [True] * hi
        prime[0] = prime[1] = False
        for p in range(2, int((hi - 1) ** 0.5) + 1):
            if prime[p]:
                for multiple in range(p * p, hi, p):
                    prime[multiple] = False

        if prime[n] or prime[m]:
            return -1

        # A path's cost includes the value at its starting point and every
        # subsequent value, so entering a vertex adds that vertex's value.
        dist = [float('inf')] * hi
        dist[n] = n
        pq = [(n, n)]
        places = [10 ** i for i in range(length)]

        while pq:
            cost, x = heapq.heappop(pq)
            if cost != dist[x]:
                continue
            if x == m:
                return cost

            for place in places:
                digit = (x // place) % 10
                if digit < 9:
                    y = x + place
                    if y >= lo and not prime[y] and cost + y < dist[y]:
                        dist[y] = cost + y
                        heapq.heappush(pq, (dist[y], y))
                if digit > 0:
                    y = x - place
                    if y >= lo and not prime[y] and cost + y < dist[y]:
                        dist[y] = cost + y
                        heapq.heappush(pq, (dist[y], y))

        return -1

