from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)

        # Z-array of nums: z[i] is the LCP of nums and nums[i:].
        z = [0] * n
        left = right = 0
        for i in range(1, n):
            if i < right:
                z[i] = min(right - i, z[i - left])
            while i + z[i] < n and nums[z[i]] == nums[i + z[i]]:
                z[i] += 1
            if i + z[i] > right:
                left, right = i, i + z[i]

        answer = 0
        for first_len in range(1, n - 1):
            first_condition = z[first_len] >= first_len
            # For each valid second_len d, the second condition compares
            # nums[first_len:first_len+d] with the following length-d block.
            if first_condition and 2 * first_len < n:
                answer += n - 2 * first_len

            m = n - first_len
            local_z = [0] * m
            left = right = 0
            for i in range(1, m):
                if i < right:
                    local_z[i] = min(right - i, local_z[i - left])
                while i + local_z[i] < m and nums[first_len + local_z[i]] == nums[first_len + i + local_z[i]]:
                    local_z[i] += 1
                if i + local_z[i] > right:
                    left, right = i, i + local_z[i]

            # A second part of length d can be a prefix of the third part
            # only when 2*d <= m.
            for d in range(1, m // 2 + 1):
                if local_z[d] >= d:
                    answer += 1
                    # This split was already included by the first condition.
                    if first_condition and d >= first_len:
                        answer -= 1

        return answer

