class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        # Z values for the whole array, for nums[0:i] == nums[i:2i]
        z = [0] * n
        l = r = 0
        for k in range(1, n):
            if k < r:
                z[k] = min(r - k, z[k - l])
            while k + z[k] < n and nums[z[k]] == nums[k + z[k]]:
                z[k] += 1
            if k + z[k] > r:
                l, r = k, k + z[k]
        ans = 0
        for i in range(1, n - 1):
            first_ok = z[i] >= i
            # Z on the suffix nums[i:], to compare nums[i:i+d] with nums[i+d:i+2d].
            m = n - i
            w = [0] * m
            l = r = 0
            for k in range(1, m):
                if k < r:
                    w[k] = min(r - k, w[k - l])
