def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    k = int(data[0])
    s = data[1].decode()
    t = data[2].decode()

    if s == t:
        print("Yes")
        return
    if abs(len(s) - len(t)) > k:
        print("No")
        return

    if len(s) == len(t):
        mismatches = 0
        for a, b in zip(s, t):
            if a != b:
                mismatches += 1
                if mismatches > k:
                    break
        print("Yes" if mismatches <= k else "No")
        return

    # The lengths differ by one. Check whether the shorter string is
    # a subsequence of the longer after skipping at most one character.
    if len(s) > len(t):
        s, t = t, s
    i = j = 0
    skipped = 0
    while i < len(s) and j < len(t):
        if s[i] == t[j]:
            i += 1
            j += 1
        else:
            skipped += 1
            j += 1
            if skipped > k:
                break
    print("Yes" if skipped <= k else "No")

