class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        # Reversing edges lets us search from node 0 to find nodes that can
        # reach 0 in the original graph.
        reverse_graph = [[] for _ in range(n)]
        max_weight = 0
        for a, b, weight in edges:
            reverse_graph[b].append((a, weight))
            max_weight = max(max_weight, weight)

        def can_reach_all(limit: int) -> bool:
            visited = bytearray(n)
            visited[0] = 1
            stack = [0]
            count = 1
            while stack:
                node = stack.pop()
                for predecessor, weight in reverse_graph[node]:
                    if weight <= limit and not visited[predecessor]:
                        visited[predecessor] = 1
                        count += 1
                        stack.append(predecessor)
            return count == n

        if not can_reach_all(max_weight):
            return -1

        low, high = 1, max_weight
        while low < high:
            mid = (low + high) // 2
            if can_reach_all(mid):
                high = mid
            else:
                low = mid + 1
        return low

