from typing import List

class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        # Each state assigns colors to a symmetric pair (i, n-1-i).
        # The two colors must differ, leaving six possible ordered pairs.
        pairs = [(a, b) for a in range(3) for b in range(3) if a != b]
        m = n // 2

        dp = [cost[0][a] + cost[n - 1][b] for a, b in pairs]

        # Move inward from the ends. Consecutive pair states must differ
        # in both components to satisfy adjacency on both sides.
        for i in range(1, m):
            next_dp = []
            for a, b in pairs:
                pair_cost = cost[i][a] + cost[n - 1 - i][b]
                best_prev = min(
                    dp[k]
                    for k, (x, y) in enumerate(pairs)
                    if x != a and y != b
                )
                next_dp.append(pair_cost + best_prev)
            dp = next_dp

        return min(dp)

